async def test_query_recursive_shapes_response_recursive_xml_shapes() -> None:
    """Serializes recursive structures"""
    client = AsyncQueryProtocolClient(
        config=await AsyncQueryProtocolConfig.resolve(
            endpoint_uri="https://example.com",
            transport=ResponseTestHTTPClient(
                status=200,
                headers=[("Content-Type", "text/xml")],
                body=b'<RecursiveXmlShapesResponse xmlns="https://example.com/">\n    <RecursiveXmlShapesResult>\n        <nested>\n            <foo>Foo1</foo>\n            <nested>\n                <bar>Bar1</bar>\n                <recursiveMember>\n                    <foo>Foo2</foo>\n                    <nested>\n                        <bar>Bar2</bar>\n                    </nested>\n                </recursiveMember>\n            </nested>\n        </nested>\n    </RecursiveXmlShapesResult>\n</RecursiveXmlShapesResponse>\n',
            ),
            region="us-east-1",
            aws_access_key_id="test-access-key-id",
            aws_secret_access_key="test-secret-access-key",
            aws_credentials_identity_resolver=StaticCredentialsResolver(),
        )
    )

    input_ = RecursiveXmlShapesInput()

    try:
        actual = await client.recursive_xml_shapes(input_)
    except Exception as err:
        fail(f"Expected a valid response, but received: {type(err).__name__}: {err}")
    else:
        expected = RecursiveXmlShapesOutput(
            nested=RecursiveXmlShapesOutputNested1(
                foo="Foo1",
                nested=RecursiveXmlShapesOutputNested2(
                    bar="Bar1",
                    recursive_member=RecursiveXmlShapesOutputNested1(
                        foo="Foo2", nested=RecursiveXmlShapesOutputNested2(bar="Bar2")
                    ),
                ),
            )
        )

        assert deep_equal(actual, expected)


